(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  let wy = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  wx += Math.sin((x+y)*0.01+t*0.5)*8+Math.cos((x-y)*0.012-t*0.4)*6;
  wy += Math.cos((x+y)*0.011-t*0.45)*7+Math.sin((x-y)*0.013+t*0.55)*5;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.0],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.0],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.0],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4.0],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,5.0],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*60,0.11,2.1,0.5],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*50,0.05,2.8,3.5],
    [200+Math.sin(t*0.38+6)*110,220+Math.cos(t*0.48+2)*70,0.085,1.8,1.5],
    [300+Math.cos(t*0.42+1)*90,30+Math.sin(t*0.58+3)*55,0.095,2.4,4.5]
  ];
  let aS=0,iS=0,mS=0,nS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1=Math.sin(d*f-t*sp+ph);
    const w2=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5);
    const w3=Math.sin(d*f*1.3-t*sp*0.4+ph*0.7);
    const w4=Math.cos(d*f*0.5+t*sp*0.8+ph*1.3);
    aS+=w1; iS+=w2; mS+=w3; nS+=w4;
  }
  const n=src.length;
  const act=aS/n, inh=iS/n, mod=mS/n, aux=nS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg2=(Math.sin(sx*0.07-sy*0.05+t*1.8)+Math.cos(sx*0.05+sy*0.08-t*1.4))*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=Math.sin(dist*0.08+ang*2-t*2.5)*Math.cos(dist*0.03-ang*5+t*1.8)*0.25;
  const cross=Math.sin(act*Math.PI)*Math.cos(inh*Math.PI*0.8)*0.3;
  const ripple=Math.sin(dist*0.15-t*3)*Math.exp(-dist*0.008)*0.4;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+mod*0.15)*2.2);
  const reaction2=Math.tanh((aux-mod*0.5+bg2+spiral2+ripple)*1.8);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const voronoi=()=>{
    let md=1e9,md2=1e9;
    for(let i=0;i<src.length;i++){
      const[sX,sY]=src[i];
      const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
      if(d<md){md2=md;md=d;}else if(d<md2)md2=d;
    }
    return Math.sin((md2-md)*0.3)*0.2;
  };
  const blend=reaction*0.5+cell*0.15+reaction2*0.2+cross*0.1+voronoi()*0.05;
  const v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,42,82],[18,78,108],[28,118,118],[38,152,128],
    [120,168,80],[195,175,60],[215,140,65],[210,95,65],[180,60,72],
    [130,38,68],[85,22,58],[45,14,48],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.18:Math.abs(reaction2)>0.6?1.1:1.0;
  const glow=Math.max(0,Math.sin(reaction*Math.PI)*0.12);
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*30)|0)
  ];
}
